/**
 * Phone validation field highlighting for WooCommerce block checkout.
 *
 * Presentation only. Block checkout shows Store API errors in a generic banner
 * with no reference to the field. The banner text is compared with the exact
 * messages generated by PHP for the current locale (window.shift64PhoneValidation,
 * see Checkout\Assets) to recognise our notice; no wording lives in this file.
 *
 * Which field the notice is about comes from the checkout response itself
 * (data.field of the Store API error, read through a wp.apiFetch middleware),
 * because a theme may reword both fields' messages to the same text (#52).
 * Without it the text decides, and text that fits both fields highlights none.
 *
 * Scrolling is left to WooCommerce Blocks.
 *
 * @package Shift64\SmartPhoneValidation
 */

(function() {
	'use strict';

	var config = window.shift64PhoneValidation || {};
	var messages = config.messages || {};
	var FIELD_TYPES = ['billing', 'shipping'];
	var NOTICE_SELECTOR = '.wc-block-components-notice-banner.is-error, .wc-block-store-notice.is-error';
	var CHECKOUT_PATH = /\/wc\/store(\/v\d+)?\/checkout\/?(\?|$)/;
	// WooCommerce Blocks' saved-address card and its form; .is-editing marks it open.
	var ADDRESS_WRAPPER_SELECTOR = '.wc-block-components-address-address-wrapper';
	var ADDRESS_EDIT_SELECTOR = '.wc-block-components-address-card__edit';

	// Field type of the phone error in the last place-order response, if any.
	var responseFieldType = null;

	/**
	 * Find the phone input for a field type.
	 *
	 * With "use same address for billing" checked only the shipping form is
	 * rendered and its phone doubles as the billing phone.
	 *
	 * @param {string} type 'billing' or 'shipping'.
	 * @return {Element|null} The input element or null.
	 */
	function findPhoneField(type) {
		var field = document.getElementById(type + '-phone');

		if (!field && type === 'billing') {
			field = document.getElementById('shipping-phone');
		}

		return field;
	}

	function findFieldWrapper(input) {
		return input.closest('.wc-block-components-text-input') || input.parentElement;
	}

	function markField(input, type) {
		// .has-error is the class WooCommerce Blocks styles itself.
		findFieldWrapper(input).classList.add('has-error');
		input.setAttribute('aria-invalid', 'true');
		input.setAttribute('data-shift64-phone-error', type);
	}

	/**
	 * Open the address form a phone field sits in when it is collapsed.
	 *
	 * A saved address is shown as a summary card, with the form still in the page
	 * but hidden, so a mark on its phone field cannot be seen (#54). The card's own
	 * Edit control opens it, as the shopper would. An open form is left alone.
	 *
	 * @param {Element} input Phone input.
	 * @return {boolean} Whether the form was opened.
	 */
	function openCollapsedAddress(input) {
		var wrapper = input.closest(ADDRESS_WRAPPER_SELECTOR);
		var edit;

		if (!wrapper || wrapper.classList.contains('is-editing')) {
			return false;
		}

		edit = wrapper.querySelector(ADDRESS_EDIT_SELECTOR);
		if (!edit) {
			return false;
		}

		edit.click();

		return true;
	}

	function highlightField(type) {
		var input = findPhoneField(type);
		if (!input) {
			return;
		}

		markField(input, type);

		if (openCollapsedAddress(input)) {
			// React re-renders the form it has just opened; mark it again after that.
			window.requestAnimationFrame(function() {
				var field = findPhoneField(type);

				if (field) {
					markField(field, type);
				}
			});
		}
	}

	function clearFieldError(input) {
		findFieldWrapper(input).classList.remove('has-error');
		input.setAttribute('aria-invalid', 'false');
		input.removeAttribute('data-shift64-phone-error');
	}

	function matchesAny(text, list) {
		for (var i = 0; i < list.length; i++) {
			if (text.indexOf(list[i]) !== -1) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Tell which phone field a notice is about.
	 *
	 * @param {string} text Notice text.
	 * @return {string|null} 'billing', 'shipping' or null when it is not our notice
	 *                       or the field cannot be told.
	 */
	function detectFieldType(text) {
		var matches = FIELD_TYPES.filter(function(type) {
			return matchesAny(text, messages[type] || []);
		});

		if (!matches.length) {
			return null;
		}

		if (responseFieldType) {
			return responseFieldType;
		}

		return matches.length === 1 ? matches[0] : null;
	}

	/**
	 * Read the field type from a Store API error body.
	 *
	 * @param {Object} error Parsed error, e.g. { code: 'invalid_shipping_phone', data: { field: 'shipping_phone' } }.
	 * @return {string|null} 'billing', 'shipping' or null.
	 */
	function fieldTypeFromError(error) {
		var field = error && error.data && error.data.field;
		var match = typeof field === 'string' && field.match(/^(billing|shipping)_phone$/);

		if (!match && error && typeof error.code === 'string') {
			match = error.code.match(/^invalid_(billing|shipping)_phone$/);
		}

		return match ? match[1] : null;
	}

	function rememberResponseError(error) {
		var type = fieldTypeFromError(error);

		if (type) {
			responseFieldType = type;
			processNotices();
		}
	}

	/**
	 * Watch the place-order request for our Store API error.
	 *
	 * The request and its result are passed through untouched. WooCommerce reads the
	 * raw Response itself (parse: false), so the body is read from a clone.
	 */
	function watchCheckoutRequests() {
		var apiFetch = window.wp && window.wp.apiFetch;

		if (!apiFetch || typeof apiFetch.use !== 'function') {
			return;
		}

		apiFetch.use(function(options, next) {
			var path = options.path || options.url || '';
			var method = (options.method || 'GET').toUpperCase();

			if (method !== 'POST' || !CHECKOUT_PATH.test(path)) {
				return next(options);
			}

			responseFieldType = null;

			return next(options).catch(function(error) {
				try {
					if (error && typeof error.clone === 'function') {
						error.clone().json().then(rememberResponseError, function() {});
					} else {
						rememberResponseError(error);
					}
				} catch (e) {
					// Highlighting is best effort; never get in the way of the checkout.
				}

				throw error;
			});
		});
	}

	function processNotices() {
		document.querySelectorAll(NOTICE_SELECTOR).forEach(function(notice) {
			var type = detectFieldType(notice.textContent || '');

			if (type) {
				highlightField(type);
			}
		});
	}

	function containsNotice(node) {
		return node.nodeType === 1 && (node.matches(NOTICE_SELECTOR) || node.querySelector(NOTICE_SELECTOR));
	}

	function init() {
		processNotices();

		// Notices are rendered by React after the Store API responds.
		new MutationObserver(function(mutations) {
			var noticeAdded = mutations.some(function(mutation) {
				return Array.prototype.some.call(mutation.addedNodes, containsNotice);
			});

			if (noticeAdded) {
				processNotices();
			}
		}).observe(document.body, { childList: true, subtree: true });

		// Delegated, so it also covers fields React renders later.
		document.addEventListener('input', function(event) {
			if (event.target.hasAttribute && event.target.hasAttribute('data-shift64-phone-error')) {
				clearFieldError(event.target);
			}
		});
	}

	watchCheckoutRequests();

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init);
	} else {
		init();
	}

})();
